#!/usr/bin/env bash
# Phase 5 - shell, dotfiles, desktop.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
DOTFILES_DIR="$(dirname "$SCRIPT_DIR")"

# ------------------------------------------------------------------- zsh
setup_zsh() {
  echo "==> Oh My Zsh, plugins and fonts"
  RUNZSH=no CHSH=no bash "$DOTFILES_DIR/scripts/ohMyZshInstall.sh" || true

  echo "==> Ubuntu-specific shell overrides"
  # Debian renames both binaries; keep the names the rest of the configs use.
  cat >"$HOME/.oh-my-zsh/custom/ubuntu.zsh" <<'ZSH'
# Generated by ubuntu/30-configure.sh - not tracked by the repo.
# Debian/Ubuntu ship these under different binary names.
command -v batcat >/dev/null && alias bat='batcat'
command -v fdfind >/dev/null && alias fd='fdfind'
ZSH

  if [ "$SHELL" != "$(command -v zsh)" ]; then
    echo "==> Setting zsh as the login shell"
    chsh -s "$(command -v zsh)" || echo "    chsh failed; run it by hand"
  fi
}

# ---------------------------------------------------------------- lazyvim
install_lazyvim() {
  echo "==> LazyVim"
  if [ -d "$HOME/.config/nvim" ] && [ ! -L "$HOME/.config/nvim" ]; then
    echo "    ~/.config/nvim exists; leaving it alone"
    return 0
  fi
  git clone https://github.com/LazyVim/starter.git "$HOME/.config/nvim"
  rm -rf "$HOME/.config/nvim/.git"
}

# ------------------------------------------------------------------- stow
run_stow() {
  echo "==> stow"
  local backup_dir="$DOTFILES_DIR/.stow_backups/$(date +%s)"
  mkdir -p "$backup_dir"

  # Files a fresh install creates that stow would otherwise refuse to replace.
  local paths=(
    "$HOME/.zshrc"
    "$HOME/.zshenv"
    "$HOME/.zprofile"
    "$HOME/.config/dolphinrc"
    "$HOME/.config/kglobalshortcutsrc"
    "$HOME/.config/kdeglobals"
    "$HOME/.config/spectaclerc"
    "$HOME/.config/nvim/lua/config/keymaps.lua"
  )

  local p dest
  for p in "${paths[@]}"; do
    [ -e "$p" ] && [ ! -L "$p" ] || continue
    dest="$backup_dir${p#"$HOME"}"
    mkdir -p "$(dirname "$dest")"
    cp -a "$p" "$dest"
    rm -rf "$p"
    echo "    backed up and removed $p"
  done

  (cd "$DOTFILES_DIR" && stow --ignore='^\.config/firefox$' -t "$HOME" home) &&
    echo "    stow completed" || {
    echo "    stow reported conflicts. Resolve the files it listed, then:"
    echo "      (cd $DOTFILES_DIR && stow -t \$HOME home)"
  }
}

# ---------------------------------------------------------- claude skills
link_claude_skills() {
  echo "==> Linking Claude skills"
  local src="$HOME/.agents/skills"
  local dest="$HOME/.claude/skills"
  [ -d "$src" ] || {
    echo "    $src not present; skipping"
    return 0
  }
  mkdir -p "$dest"
  local skill name
  for skill in "$src"/*; do
    [ -d "$skill" ] || continue
    name="$(basename "$skill")"
    [ -e "$dest/$name" ] || ln -s "../../.agents/skills/$name" "$dest/$name"
  done
}

# -------------------------------------------------------------------- kwin
update_kwinrc() {
  local kwinrc="$HOME/.config/kwinrc"
  echo "==> kwinrc"
  if [ -f "$kwinrc" ]; then
    cp "$kwinrc" "$kwinrc.backup.$(date +%s)"
  else
    mkdir -p "$(dirname "$kwinrc")"
    touch "$kwinrc"
  fi

  python3 - "$kwinrc" <<'PY'
import os
import sys
from configparser import ConfigParser

path = sys.argv[1]
cfg = ConfigParser()
cfg.optionxform = str
cfg.read(path)

sections = {
    'Plugins': {
        'blurEnabled': 'false',
        'diminactiveEnabled': 'true',
        'forceblurEnabled': 'true',
        'krohnkiteEnabled': 'true',
        'slideEnabled': 'false',
    },
    'Script-krohnkite': {
        'screenGapBetween': '10',
        'screenGapBottom': '10',
        'screenGapLeft': '10',
        'screenGapRight': '10',
        'screenGapTop': '10',
    },
    'Windows': {
        'FocusPolicy': 'FocusFollowsMouse',
    },
}

for sec, items in sections.items():
    if not cfg.has_section(sec):
        cfg.add_section(sec)
    for key, value in items.items():
        cfg.set(sec, key, value)

tmp = path + '.tmp'
with open(tmp, 'w') as handle:
    for sec in sorted(cfg.sections(), key=lambda s: s.lower()):
        handle.write(f"[{sec}]\n")
        for key in cfg[sec]:
            handle.write(f"{key}={cfg[sec][key]}\n")
        handle.write('\n')
os.replace(tmp, path)
print('    kwinrc updated')
PY
}

# ---------------------------------------------------------------- firefox
setup_firefox_config() {
  echo "==> Firefox profile symlink and custom CSS"
  local base profile dest user_js
  for base in \
    "$HOME/.mozilla/firefox" \
    "$HOME/snap/firefox/common/.mozilla/firefox"; do
    [ -d "$base" ] || continue

    profile=$(find "$base" -maxdepth 1 -type d -name '*.default-release' | head -n1)
    [ -n "$profile" ] || profile=$(find "$base" -maxdepth 1 -type d -name '*.default' | head -n1)
    [ -n "$profile" ] || continue

    dest="$HOME/.config/firefox"
    if [ -L "$dest" ] && [ "$(readlink -f "$dest")" = "$(readlink -f "$profile")" ]; then
      echo "    symlink already correct"
    else
      [ -e "$dest" ] && mv "$dest" "$dest.backup.$(date +%s)"
      ln -s "$profile" "$dest"
    fi

    user_js="$profile/user.js"
    touch "$user_js"
    grep -q 'toolkit.legacyUserProfileCustomizations.stylesheets' "$user_js" ||
      echo 'user_pref("toolkit.legacyUserProfileCustomizations.stylesheets", true);' >>"$user_js"
    return 0
  done
  echo "    no Firefox profile yet; run Firefox once and re-run this script"
}

# ------------------------------------------------------------------ remote
switch_remote_to_ssh() {
  if [ -f "$HOME/.ssh/id_ed25519" ]; then
    echo "==> Switching the dotfiles remote to SSH"
    (cd "$DOTFILES_DIR" && git remote set-url origin git@github.com:MrFacundo/dotfiles.git)
  fi
}

main() {
  setup_zsh
  install_lazyvim
  run_stow
  link_claude_skills
  update_kwinrc
  setup_firefox_config
  switch_remote_to_ssh

  echo
  echo "Configure done. Next: 40-restore.sh"
  echo "Still manual: KDE Store widgets and scripts (krohnkite,"
  echo "virtual-desktops-only-on-primary, forceblur, rounded corners,"
  echo "geometry change) - see ubuntu/README.md"
}

main "$@"
